#include <iostream>
#include <algorithm>
#include <limits>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

void print(i128 value) {
    if (value == 0) {
        cout << '0';
        return;
    }
    if (value < 0) {
        cout << '-';
        value = -value;
    }
    string s;
    while (value > 0) {
        s.push_back(char('0' + value % 10));
        value /= 10;
    }
    reverse(s.begin(), s.end());
    cout << s;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n;
    cin >> n;

    i128 mn = -1;

    for (int64 a = 1; (i128)a * a * a <= n; ++a) {
        if (n % a != 0) continue;

        int64 remaining = n / a;
        for (int64 b = a; b <= remaining / b; ++b) {
            if (remaining % b != 0) continue;

            int64 c = remaining / b;
            i128 current = (i128)(a + 1) * (b + 2) * (c + 2) - n;

            if (mn == -1 || current < mn)
                mn = current;
        }
    }

    i128 mx = (i128)(n + 1) * 3 * 3 - n;

    print(mn);
    cout << ' ';
    print(mx);
    cout << '\n';

    return 0;
}

